package com.yihe.framework.ehr;
import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import javax.servlet.http.*;import java.nio.file.*;import java.io.*;import java.util.*;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrController.ok;
@RestController @RequestMapping("/ehr/api/intervention-templates")
public class InterventionTemplateApi{
 private final EhrAccess access;private final EhrRepository db;private final ObjectMapper json=new ObjectMapper();@Value("${ehr.storage-root:${EHR_STORAGE_ROOT:D:/update}}") private String storage;
 public InterventionTemplateApi(EhrAccess a,EhrRepository d){access=a;db=d;}@ModelAttribute public void headers(HttpServletResponse r){r.setHeader("Cache-Control","private, no-store");}private String s(Object v){return v==null?"":String.valueOf(v);}private void check(boolean b,String m){if(!b)throw new EhrException(422,m);}private Path file(EhrActor a){return Paths.get(storage,".intervention-templates",Base64.getUrlEncoder().withoutPadding().encodeToString(digest(bytes(a.scope+":"+a.mode)))+".json");}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> rows(Object v,int max){check(v instanceof List&&((List<?>)v).size()<=max,"列表格式无效或超过限制");List<Map<String,Object>> out=new ArrayList<>();for(Object r:(List<?>)v){check(r instanceof Map,"行格式无效");out.add((Map<String,Object>)r);}return out;}
 private Map<String,Object> initial(EhrActor a){List<Object> categories=new ArrayList<>(),contents=new ArrayList<>(),followups=new ArrayList<>(),templates=new ArrayList<>();Map<String,String> names=new HashMap<>();for(Map<String,Object> row:db.all("SELECT disease_code code,MIN(disease_name) name FROM yh_disease_category GROUP BY disease_code ORDER BY disease_code")){String id="category-"+row.get("code");categories.add(map("id",id,"name",row.get("name"),"description","","enabled",true));names.put(s(row.get("code")),s(row.get("name")));}categories.add(map("id","uncategorized","name","未分类","description","","enabled",true));Set<String> contentIds=new HashSet<>();Map<String,String> contentNames=new HashMap<>();for(Map<String,Object> row:db.all("SELECT plancount_id id,plan_count name FROM yh_programs_dictionary ORDER BY plancount_id")){String name=s(row.get("name"));if(name.trim().isEmpty())continue;String id="content-"+row.get("id");contents.add(map("id",id,"name",name,"body",name,"enabled",true,"type","干预内容"));contentIds.add(id);contentNames.put(id,name);}
 List<Map<String,Object>> source=db.all("SELECT * FROM yh_intervention_template WHERE COALESCE(souce_isdelete,0)=0 AND (source_type=1 OR operation='0' OR operation=?) ORDER BY intervention_id",a.user);Set<String> available=new HashSet<>();Map<String,String> templateNames=new HashMap<>();for(Map<String,Object> row:source){available.add(s(row.get("intervention_id")));templateNames.put(s(row.get("intervention_id")),s(row.get("template_name")));}Map<String,List<String>> templateContents=new HashMap<>(),templateFollowups=new HashMap<>();Map<String,Integer> weeks=new HashMap<>();for(Map<String,Object> row:db.all("SELECT programs_id id,Intervention_id templateId,programs_weeks week,programs_days day,service_way channel,plan_content contentId,content_prompt prompt FROM yh_programs_template ORDER BY Intervention_id,programs_weeks,programs_days,programs_id")){String tid=s(row.get("templateId"));if(!available.contains(tid))continue;int week=EhrService.num(row.get("week")),day=EhrService.num(row.get("day"));String content="content-"+s(row.get("contentId")),id="followup-"+row.get("id");followups.add(map("id",id,"name",templateNames.get(tid)+" · "+(week>0?"第"+week+"周":"周次待配置")+" · "+(day>0?"第"+day+"天":"天次待配置")+" · "+contentNames.getOrDefault(content,"随访"),"week",week,"day",day,"channel",s(row.get("channel")),"contentId",contentIds.contains(content)?content:"","prompt",s(row.get("prompt")),"enabled",true));templateFollowups.computeIfAbsent(tid,k->new ArrayList<>()).add(id);if(contentIds.contains(content)&&!templateContents.computeIfAbsent(tid,k->new ArrayList<>()).contains(content))templateContents.get(tid).add(content);weeks.put(tid,Math.max(weeks.getOrDefault(tid,0),week));}
 for(Map<String,Object> row:source){String id=s(row.get("intervention_id")),disease=s(row.get("template_diseases")),sex=s(row.get("apply_sex"));List<String> applicability=new ArrayList<>();if(sex.equals("1"))applicability.add("男");if(sex.equals("2"))applicability.add("女");if(row.get("apply_age_min")!=null||row.get("apply_age_max")!=null)applicability.add("年龄："+s(row.get("apply_age_min"))+"–"+s(row.get("apply_age_max")));if(row.get("apply_bim_min")!=null||row.get("apply_bim_max")!=null)applicability.add("BMI："+s(row.get("apply_bim_min"))+"–"+s(row.get("apply_bim_max")));templates.add(map("id","template-"+id,"name",s(row.get("template_name")).isEmpty()?"原方案 "+id:row.get("template_name"),"categoryId",names.containsKey(disease)?"category-"+disease:"uncategorized","problem",names.getOrDefault(disease,""),"population",String.join("；",applicability),"conditions",s(row.get("template_risk")).isEmpty()?"":"原风险分层编码："+s(row.get("template_risk")).replace(",","、"),"weeks",weeks.getOrDefault(id,0),"goals","","description",s(row.get("template_describe")),"reference","","effectiveDate","","enabled",true,"contentIds",templateContents.getOrDefault(id,new ArrayList<>()),"followupIds",templateFollowups.getOrDefault(id,new ArrayList<>()),"metrics",new ArrayList<>(),"revision",1,"updatedAt",s(row.get("insert_time"))));}return map("version",0,"templates",templates,"categories",categories,"contents",contents,"followups",followups,"history",new ArrayList<>());}
 @SuppressWarnings("unchecked") private Map<String,Object> read(EhrActor a)throws IOException{Path p=file(a);if(!Files.exists(p))return initial(a);check(Files.size(p)<=12582912,"配置文件过大");return json.readValue(Files.readAllBytes(p),Map.class);}
 private void write(EhrActor a,Map<String,Object> data)throws IOException{byte[] bytes=json.writeValueAsBytes(data);check(bytes.length<=12582912,"配置超过12MB");Path p=file(a);Files.createDirectories(p.getParent());Path t=Files.createTempFile(p.getParent(),"template-",".tmp");try{Files.write(t,bytes);try{Files.move(t,p,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException ex){Files.move(t,p,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(t);}}
 private void text(Map<String,Object> r,String key,int max,boolean required){String v=s(r.get(key));check(v.length()<=max&&(!required||!v.trim().isEmpty()),"字段 "+key+" 为空或超长");}private Set<String> ids(List<Map<String,Object>> rows){Set<String> ids=new HashSet<>();for(Map<String,Object> r:rows){text(r,"id",100,true);text(r,"name",200,true);check(ids.add(s(r.get("id"))),"标识重复");}return ids;}
 private void refs(Object value,Set<String> ids){check(value instanceof List&&((List<?>)value).size()<=500,"引用列表无效");for(Object v:(List<?>)value)check(ids.contains(s(v)),"引用的分类、内容或随访模板不存在");}
 @GetMapping public synchronized Object get(HttpServletRequest req)throws IOException{return ok(read(access.web(req)));}
 @PutMapping public synchronized Object save(HttpServletRequest req,@RequestBody Map<String,Object> body)throws IOException{EhrActor a=access.web(req);Map<String,Object> old=read(a);if(EhrService.num(old.get("version"))!=EhrService.num(body.get("version")))throw new EhrException(409,"模板资料已被其他人员修改，请刷新后重试");List<Map<String,Object>> templates=rows(body.get("templates"),2000),categories=rows(body.get("categories"),1000),contents=rows(body.get("contents"),3000),followups=rows(body.get("followups"),5000),history=rows(old.get("history"),200),previous=rows(old.get("templates"),2000);Set<String> tids=ids(templates),cids=ids(categories),contentIds=ids(contents),fids=ids(followups);for(Map<String,Object> c:contents)text(c,"body",10000,true);for(Map<String,Object> f:followups){int week=EhrService.num(f.get("week")),day=EhrService.num(f.get("day"));check(week>=0&&week<=520&&day>=0&&day<=366,"随访时间超出范围");check(s(f.get("contentId")).isEmpty()||contentIds.contains(s(f.get("contentId"))),"随访关联内容不存在");text(f,"prompt",2000,false);}
 for(Map<String,Object> t:templates){check(cids.contains(s(t.get("categoryId"))),"方案所属分类不存在");text(t,"problem",1000,false);text(t,"population",1000,false);text(t,"conditions",3000,false);text(t,"goals",5000,false);text(t,"description",5000,false);text(t,"reference",2000,false);check(t.get("weeks") instanceof Number&&EhrService.num(t.get("weeks"))>=0&&EhrService.num(t.get("weeks"))<=520,"干预周期须为0–520周");String date=s(t.get("effectiveDate"));if(!date.isEmpty())try{java.time.LocalDate.parse(date);}catch(Exception ex){throw new EhrException(422,"生效日期无效");}refs(t.get("contentIds"),contentIds);refs(t.get("followupIds"),fids);if(EhrService.num(t.get("weeks"))>0)for(Object fid:(List<?>)t.get("followupIds")){Map<String,Object> event=followups.stream().filter(f->s(f.get("id")).equals(s(fid))).findFirst().get();check(EhrService.num(event.get("week"))<=EhrService.num(t.get("weeks")),"关联随访计划的周次超出干预周期");}check(t.get("metrics") instanceof List&&((List<?>)t.get("metrics")).size()<=100,"评估指标格式无效");for(Object metric:(List<?>)t.get("metrics"))check(s(metric).length()<=300&&!s(metric).trim().isEmpty(),"评估指标不能为空或超过300字");Map<String,Object> prior=previous.stream().filter(p->s(p.get("id")).equals(s(t.get("id")))).findFirst().orElse(null);if(prior==null||!json.writeValueAsString(prior).equals(json.writeValueAsString(t))){if(prior!=null)history.add(map("id",UUID.randomUUID().toString(),"templateId",prior.get("id"),"name",prior.get("name"),"revision",prior.get("revision"),"savedAt",now(),"savedBy",a.user,"snapshot",prior));t.put("revision",prior==null?1:EhrService.num(prior.get("revision"))+1);t.put("updatedAt",now());}}
 for(Map<String,Object> p:previous)if(!tids.contains(s(p.get("id"))))history.add(map("id",UUID.randomUUID().toString(),"templateId",p.get("id"),"name",p.get("name"),"revision",p.get("revision"),"savedAt",now(),"savedBy",a.user,"snapshot",p));if(history.size()>100)history=new ArrayList<>(history.subList(history.size()-100,history.size()));Map<String,Object> next=map("version",EhrService.num(old.get("version"))+1,"templates",templates,"categories",categories,"contents",contents,"followups",followups,"history",history);write(a,next);return ok(next);}
}
